set -e
cd /tmp/pbin
cat > Program.cs <<'EOF'
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text.Json;
using Microsoft.Extensions.Configuration;

class Probe {
  static List<KeyValuePair<string,string>> Flatten(string path) {
    var pairs = new List<KeyValuePair<string,string>>();
    if (!File.Exists(path)) return pairs;
    var doc = JsonDocument.Parse(File.ReadAllText(path));
    void Rec(JsonElement el, string prefix) {
      if (el.ValueKind == JsonValueKind.Object) {
        foreach (var p in el.EnumerateObject()) Rec(p.Value, prefix.Length==0 ? p.Name : prefix + ":" + p.Name);
      } else {
        pairs.Add(new KeyValuePair<string,string>(prefix, el.ValueKind == JsonValueKind.String ? el.GetString() : el.GetRawText()));
      }
    }
    Rec(doc.RootElement, "");
    return pairs;
  }
  static void Main(string[] args) {
    var baseDir = AppContext.BaseDirectory;
    var list = Flatten(baseDir + "appsettings.json")
              .Concat(Flatten(baseDir + "appsettings.Development.json"))
              .Concat(Flatten(baseDir + "local.json")).ToList();
    var config = new ConfigurationBuilder().AddInMemoryCollection(list).Build();

    var asm = Assembly.LoadFrom(baseDir + "Bovis.Web.dll");
    var ifas = Assembly.LoadFrom(baseDir + "Bovis.Interfaces.dll");
    var binderType = ifas.GetType("Bovis.Interfaces.Configuration.ConfigurableBinder", true);
    binderType.GetConstructor(new Type[]{ typeof(IConfiguration) }).Invoke(new object[]{ config });
    var globals = asm.GetType("Bovis.Web.Globals", true);
    string boundCookie = (string)globals.GetField("AuthCookie", BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);
    string boundPub = (string)globals.GetField("PublicBaseUrl", BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);
    string cfgCookie = config["Bovis.Web:AuthCookie"];
    string cfgPub = config["Bovis.Web:PublicBaseUrl"];
    Console.WriteLine("CONFIG[Bovis.Web:AuthCookie]     = " + cfgCookie);
    Console.WriteLine("CONFIG[Bovis.Web:PublicBaseUrl]  = " + cfgPub);
    Console.WriteLine("BOUND Globals.AuthCookie         = " + boundCookie);
    Console.WriteLine("BOUND Globals.PublicBaseUrl      = " + boundPub);
    Console.WriteLine("COOKIE_MATCH(appsettings==bound) = " + (boundCookie == cfgCookie));
  }
}
EOF
cat > probe.csproj <<'EOF'
